package cn.nebulaedata.cccs.nebuwork.backend.api.workbenchservice;

import cn.nebulaedata.cccs.nebuwork.backend.api.agent.*;
import cn.nebulaedata.cccs.nebuwork.backend.api.extensionmarket.ExtensionMarket;
import cn.nebulaedata.cccs.nebuwork.backend.api.extensionmarket.ExtensionRuntime;
import cn.nebulaedata.cccs.nebuwork.backend.api.expert.ExpertMapper;
import cn.nebulaedata.cccs.nebuwork.backend.api.knowledge.KnowledgeService;
import cn.nebulaedata.cccs.nebuwork.backend.api.workflow.WorkflowService;
import cn.nebulaedata.cccs.nebuwork.backend.api.workbench.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.springframework.stereotype.Service;
import java.util.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiSupport.map;
import static cn.nebulaedata.cccs.nebuwork.backend.api.workbenchservice.ServiceSupport.*;

/** Whitelisted adapters. Workflow source and environment remain wholly owned by Workflow 3.5. */
@Service
public class ServiceExecutions {
    @org.springframework.beans.factory.annotation.Autowired private cn.nebulaedata.cccs.nebuwork.backend.api.database.DatabaseRuntime databases;
    @org.springframework.beans.factory.annotation.Autowired private cn.nebulaedata.cccs.nebuwork.backend.api.platformmcp.PlatformMcpService platformMcp;
    public static final List<String> PLATFORM_OPERATIONS=Collections.unmodifiableList(Arrays.asList("project.get","project.update","task.list","knowledge.search"));
    final AgentStore db;final AgentTasks tasks;final AgentClient engine;final ObjectMapper json;final WorkflowService workflow;
    final WorkbenchService workbenches;final AgentModels models;final ExpertMapper experts;final KnowledgeService knowledge;
    public ServiceExecutions(AgentStore db,AgentTasks tasks,AgentClient engine,ObjectMapper json,WorkflowService workflow,WorkbenchService workbenches,AgentModels models,ExpertMapper experts,KnowledgeService knowledge){this.db=db;this.tasks=tasks;this.engine=engine;this.json=json;this.workflow=workflow;this.workbenches=workbenches;this.models=models;this.experts=experts;this.knowledge=knowledge;}
    void validate(String owner,String wb,JsonNode c,boolean publishing){JsonNode b=c.path("binding");String type=text(b,"type",32);
        switch(type){case "platform":fields(b,"type","operation","referenceId");require(PLATFORM_OPERATIONS.contains(b.path("operation").asText()),422,"未登记的平台操作");if(b.path("operation").asText().equals("knowledge.search")){text(b,"referenceId",128);if(publishing)for(JsonNode p:c.path("projectIds"))knowledge.readReference(owner,"project",p.asText(),b.path("referenceId").asText(),"capabilities",json.createObjectNode());}break;
        case "workflow":fields(b,"type","workflowId","inputMapping","resultStep","resultName");text(b,"workflowId",128);text(b,"resultStep",128);text(b,"resultName",240);if(b.has("inputMapping")){require(b.path("inputMapping").isObject(),422,"输入映射必须为对象");for(JsonNode pointer:b.path("inputMapping"))require(pointer.isTextual()&&(pointer.asText().isEmpty()||pointer.asText().startsWith("/")),422,"输入映射使用 JSON Pointer");}if(publishing){JsonNode flow=json.valueToTree(workflow.get(owner,b.path("workflowId").asText()));require(flow.path("enabled").asBoolean()&&flow.path("status").asText().equals("ready")&&!flow.path("archived").asBoolean(),409,"工作流未就绪或已归档");JsonNode steps=flow.path("workflow").path("definition").path("steps");require(steps.has(b.path("resultStep").asText()),422,"结果节点不存在");}break;
        case "agent":fields(b,"type","projectId","expertId","instructions");String project=text(b,"projectId",128);require(contains(c.path("projectIds"),project)&&c.path("projectIds").size()==1,422,"智能体能力首期绑定一个明确项目");if(publishing)captureAgent(owner,wb,b);break;
        default:throw new cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException(422,"未知执行类型");}
    }
    JsonNode capture(String owner,String wb,JsonNode capability){return capability.path("binding").path("type").asText().equals("agent")?captureAgent(owner,wb,capability.path("binding")):json.createObjectNode();}
    private void merge(ObjectNode target,JsonNode source){ExtensionMarket.removeShadowed(target,source);for(String field:Arrays.asList("instructions","files","skills","mcp")){ArrayNode out=target.withArray(field);for(JsonNode item:source.path(field)){String key=field.equals("files")?"path":"id";if(!field.equals("instructions"))for(int i=out.size()-1;i>=0;i--)if(out.get(i).path(key).equals(item.path(key)))out.remove(i);out.add(item.deepCopy());}}for(String field:Arrays.asList("modelProviderId","model"))if(source.hasNonNull(field))target.set(field,source.get(field));}
    private JsonNode document(String owner,String kind,String id){Map<String,Object> row=db.active(owner,kind,id);require(row!=null,422,"请先发布运行资源："+kind);return parse(json,row.get("document_json"));}
    private ArrayNode refs(String owner,String kind,String id){ArrayNode out=json.createArrayNode();for(Map<String,Object> r:knowledge.references(owner,kind,id))if(Boolean.TRUE.equals(r.get("enabled")))out.add(json.valueToTree(map("id",r.get("id"),"name",r.get("name"),"scopeKind",kind,"scopeId",id)));return out;}
    JsonNode captureAgent(String owner,String wb,JsonNode binding){String project=binding.path("projectId").asText();Map<String,Object> p=tasks.project(owner,project,true);require(engine.get(owner,project,"/v1/capabilities").path("workbenchServiceResults").asBoolean(),503,"请先升级支持服务结果提交的智能体引擎");require(wb.equals(str(p,"workbench_id")),403,"执行项目不属于工作台");JsonNode business=parse(json,p.get("snapshot_json"));ObjectNode runtime=json.createObjectNode();JsonNode workbenchRuntime=document(owner,"workbench",wb),projectRuntime=db.active(owner,"project",project)==null?json.createObjectNode():document(owner,"project",project);merge(runtime,workbenchRuntime);String primary=binding.path("expertId").asText(business.path("config").path("defaultAgentId").asText(""));ArrayNode definitions=json.createArrayNode(),allRefs=refs(owner,"project",project);
        for(JsonNode expertId:business.path("config").path("agentIds")){String expert=expertId.asText();Map<String,Object> e=experts.visibleExpert(owner,expert);if(e==null||db.active(owner,"expert",expert)==null)continue;JsonNode own=document(owner,"expert",expert);ArrayNode ownRefs=refs(owner,"project",project);ownRefs.addAll(refs(owner,"expert",expert));allRefs.addAll(refs(owner,"expert",expert));StringBuilder instructions=new StringBuilder();for(JsonNode i:own.path("instructions"))instructions.append(i.path("content").asText()).append('\n');ObjectNode effective=ExtensionRuntime.compose(json,workbenchRuntime,own,projectRuntime);ArrayNode skillIds=json.createArrayNode();for(JsonNode skill:effective.path("skills"))skillIds.add(skill.path("id"));ObjectNode item=json.valueToTree(map("id",expert,"name",e.get("name"),"instructions",instructions.toString(),"skillIds",skillIds,"runtime",map("instructions",own.path("instructions"),"files",effective.path("files"),"skills",effective.path("skills"),"mcp",effective.path("mcp"),"knowledgeReferences",ownRefs,"knowledgeRefs",ids(ownRefs))));if(own.hasNonNull("modelProviderId"))item.set("model",models.binding(owner,own));definitions.add(item);if(expert.equals(primary))merge(runtime,own);}
        if(!primary.isEmpty()){boolean found=false;for(JsonNode e:definitions)if(primary.equals(e.path("id").asText()))found=true;require(found,422,"绑定专家不可访问或尚未发布");}
        merge(runtime,projectRuntime);
        runtime.withArray("instructions").insert(0,json.valueToTree(map("source","service-business","path","BUSINESS.md","scope","","content",business.path("config").path("systemPrompt").asText()+"\n"+business.path("config").path("bizDef").asText(),"revision",str(p,"ontology_version_id"))));
        if(binding.hasNonNull("instructions"))runtime.withArray("instructions").add(json.valueToTree(map("source","service","path","SERVICE.md","scope","","content",binding.path("instructions").asText(),"revision",fingerprint(json,binding))));
        ObjectNode snapshot=json.createObjectNode();for(String field:Arrays.asList("instructions","files","skills","mcp"))snapshot.set(field,runtime.path(field));snapshot.set("model",models.binding(owner,runtime));snapshot.set("experts",definitions);if(primary.isEmpty())snapshot.putNull("primaryExpertId");else snapshot.put("primaryExpertId",primary);snapshot.set("knowledgeReferences",allRefs);snapshot.set("knowledgeRefs",ids(allRefs));JsonNode policy=platformMcp.snapshot(owner,project);if(policy!=null)snapshot.set("platformMcp",policy);databases.capture(owner,project,primary,snapshot);return snapshot;
    }
    private ArrayNode ids(JsonNode refs){ArrayNode out=json.createArrayNode();for(JsonNode r:refs)out.add(r.path("id"));return out;}
    Object platform(String owner,String project,JsonNode binding,JsonNode input){switch(binding.path("operation").asText()){
        case "project.get":Map<String,Object> p=tasks.project(owner,project,false);return projectView(p);
        case "project.update":fields(input,"revision","name","desc","status");return workbenches.updateProject(owner,project,input);
        case "task.list":return tasks.list(owner,project);
        case "knowledge.search":fields(input,"query","limit","contentKind");ObjectNode args=input.deepCopy();args.put("requireEnabled",true);return knowledge.readReference(owner,"project",project,binding.path("referenceId").asText(),"search",args);
        default:throw new cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException(422,"平台操作未实现");}}
    private Object projectView(Map<String,Object> p){return map("id",p.get("id"),"name",p.get("name"),"desc",p.get("description"),"status",p.get("status"),"revision",p.get("revision"));}
    JsonNode mapped(JsonNode binding,JsonNode input){if(!binding.has("inputMapping"))return input;ObjectNode mapped=json.createObjectNode();binding.path("inputMapping").fields().forEachRemaining(e->{JsonNode value=input.at(e.getValue().asText());require(!value.isMissingNode(),422,"输入映射缺少字段："+e.getValue().asText());mapped.set(e.getKey(),value);});return mapped;}
    String start(String owner,String project,JsonNode capability,JsonNode snapshot,String operation,JsonNode input){JsonNode b=capability.path("binding");if(b.path("type").asText().equals("workflow"))return json.valueToTree(workflow.createTask(owner,b.path("workflowId").asText(),json.valueToTree(map("input",mapped(b,input))),operation)).path("id").asText();
        String title=capability.path("name").asText();JsonNode body=json.valueToTree(map("title",title,"content","执行已发布的业务能力："+title+"。业务输入为以下 JSON 数据：\n"+input+"\n必须调用 service_result_submit 提交符合输出 Schema 的结果。","context",map("expertId",snapshot.path("primaryExpertId").asText(""))));
        return json.valueToTree(tasks.create(owner,project,body,operation)).path("task").path("id").asText();
    }
    JsonNode workflowStatus(String owner,String task){return json.valueToTree(workflow.task(owner,task));}
    JsonNode workflowResult(String owner,JsonNode capability,JsonNode status){JsonNode b=capability.path("binding"),remote=status.path("task");String step=b.path("resultStep").asText(),name=b.path("resultName").asText(),remoteId=remote.path("id").asText();JsonNode selected=null;for(JsonNode a:json.valueToTree(workflow.artifacts(owner,b.path("workflowId").asText()))){if(remoteId.equals(a.path("task_id").asText())&&step.equals(a.path("step").asText())&&name.equals(a.path("name").asText())&&"task".equals(a.path("scope").asText())&&a.path("published").asBoolean()&&a.path("effective").asBoolean()){require(selected==null,422,"本次工作流结果不唯一");selected=a;}}
        require(selected!=null,422,"本次任务未产生指定的有效成功 JSON 产物");JsonNode content=json.valueToTree(workflow.content(owner,b.path("workflowId").asText(),selected.path("id").asText()));require(!content.path("download_only").asBoolean(),422,"结果产物过大，无法作为 JSON 响应");JsonNode value=content.path("value");if(value.isMissingNode())value=content.path("data");if(value.isMissingNode()&&content.has("content")){JsonNode raw=content.path("content");if(raw.isTextual()){try{value=json.readTree(raw.asText());}catch(Exception e){throw new cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException(422,"结果不是有效 JSON");}}else value=raw;}require(!value.isMissingNode(),422,"无法读取 JSON 结果");return value;}
}
